package com.ksh321.songrecord.api.operations;
import org.junit.jupiter.api.Test;
import org.springframework.mock.env.MockEnvironment;
import static org.assertj.core.api.Assertions.*;

class DeploymentBoundaryTests {
 private MockEnvironment stage(){var e=new MockEnvironment();e.setActiveProfiles("staging");return e.withProperty("songrecord.deployment.environment","staging").withProperty("songrecord.deployment.public-origin","https://localhost:18443").withProperty("server.ssl.enabled","true").withProperty("spring.flyway.clean-disabled","true").withProperty("spring.flyway.validate-on-migrate","true").withProperty("spring.jpa.hibernate.ddl-auto","validate").withProperty("songrecord.storage.enabled","true").withProperty("songrecord.storage.environment","dev").withProperty("songrecord.storage.role","api").withProperty("songrecord.storage.dev.temporary-bucket","song-record-staging-dev-temporary").withProperty("songrecord.storage.dev.final-bucket","song-record-staging-dev-final").withProperty("DB_PASSWORD","synthetic-password").withProperty("TLS_KEYSTORE_PASSWORD","synthetic-keystore-password");}
 @Test void rejectsMixedDevelopmentAndFixtureProfiles(){for(var p:new String[]{"dev","bootstrap","candidate-fixtures","test","development"}){var e=stage();e.setActiveProfiles("staging",p);assertThatThrownBy(()->DeploymentBoundary.validate(e)).isInstanceOf(IllegalStateException.class);}}
 @Test void onlyIsolatedHttpsValidationSettingsAreAllowed(){assertThatCode(()->DeploymentBoundary.validate(stage())).doesNotThrowAnyException();for(var url:new String[]{"http://localhost:18443","https://u:p@localhost:18443","https://localhost/path","https://localhost?token=secret"})assertThatThrownBy(()->DeploymentBoundary.validate(stage().withProperty("songrecord.deployment.public-origin",url))).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->DeploymentBoundary.validate(stage().withProperty("songrecord.storage.dev.final-bucket","song-record-dev-final"))).isInstanceOf(IllegalStateException.class);}
 @Test void apiCannotExecuteDestructiveMaintenance(){for(var flag:new String[]{"songrecord.upload.scheduling-enabled","songrecord.account-deletion.worker.enabled"})assertThatThrownBy(()->DeploymentBoundary.validate(stage().withProperty(flag,"true"))).isInstanceOf(IllegalStateException.class);assertThatCode(()->DeploymentBoundary.validate(stage().withProperty("songrecord.storage.role","worker"))).doesNotThrowAnyException();}
 @Test void secretsAndDatabaseSchemaAreFailClosed(){for(var setting:new String[]{"DB_PASSWORD","TLS_KEYSTORE_PASSWORD"})assertThatThrownBy(()->DeploymentBoundary.validate(stage().withProperty(setting,""))).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->DeploymentBoundary.validate(stage().withProperty("spring.jpa.hibernate.ddl-auto","create"))).isInstanceOf(IllegalStateException.class).hasMessageNotContaining("synthetic-password");assertThatThrownBy(()->DeploymentBoundary.validate(stage().withProperty("spring.flyway.clean-disabled","false"))).isInstanceOf(IllegalStateException.class);}
}
